import Foundation

/// User-visible strings (FE-204). Keys are the English text, so a missing translation shows English.
/// The base table is `Resources/en.lproj/Localizable.strings`, regenerated by `scripts/extract-strings.sh`.
///
///     L10n.tr("Navigation pane")
///     L10n.format("%@ items selected", count)
///
/// `ARBOR_PSEUDO_LOC=1` turns every routed string into accented, 30% longer text (see `PseudoLocalization`),
/// so text that bypasses this table, and labels that clip, are easy to spot in screenshots.
public enum L10n {
    /// Pseudo-localization is on (read once; tests may set it).
    public static var pseudo: Bool = ProcessInfo.processInfo.environment["ARBOR_PSEUDO_LOC"] == "1"

    /// Bundle holding `Localizable.strings` (the app bundle).
    public static var bundle: Bundle = .main

    /// The localized text for an English key.
    public static func tr(_ key: String) -> String {
        guard !key.isEmpty else { return key }
        let value = bundle.localizedString(forKey: key, value: key, table: nil)
        return pseudo ? PseudoLocalization.transform(value) : value
    }

    /// A localized format string filled with arguments (`%@`, `%d`, `%1$@`…).
    public static func format(_ key: String, _ arguments: CVarArg...) -> String {
        String(format: tr(key), locale: Locale.current, arguments: arguments)
    }
}

/// Pseudo-localization: replaces ASCII letters with accented look-alikes, keeps format specifiers,
/// escapes and shortcut glyphs intact, pads the text to about 30% longer and brackets it, so the start
/// and end of every routed string are visible (a missing "]" means the label was cut off).
public enum PseudoLocalization {
    static let accents: [Character: Character] = [
        "a": "á", "b": "ƀ", "c": "ç", "d": "ð", "e": "é", "f": "ƒ", "g": "ĝ", "h": "ĥ", "i": "í", "j": "ĵ",
        "k": "ķ", "l": "ļ", "m": "ɱ", "n": "ñ", "o": "ö", "p": "þ", "q": "ǫ", "r": "ŕ", "s": "š", "t": "ţ",
        "u": "ü", "v": "ṽ", "w": "ŵ", "x": "ẋ", "y": "ý", "z": "ž",
        "A": "Å", "B": "Ɓ", "C": "Ç", "D": "Ð", "E": "É", "F": "Ƒ", "G": "Ĝ", "H": "Ĥ", "I": "Í", "J": "Ĵ",
        "K": "Ķ", "L": "Ļ", "M": "Ṁ", "N": "Ñ", "O": "Ö", "P": "Þ", "Q": "Ǫ", "R": "Ŕ", "S": "Š", "T": "Ţ",
        "U": "Ü", "V": "Ṽ", "W": "Ŵ", "X": "Ẋ", "Y": "Ý", "Z": "Ž",
    ]

    /// True for text this transform produced (so it isn't applied twice).
    public static func isPseudo(_ text: String) -> Bool { text.hasPrefix("[") && (text.hasSuffix("·]") || text.contains("·] ")) }

    public static func transform(_ text: String, expansion: Double = 0.3) -> String {
        guard !text.isEmpty, !isPseudo(text) else { return text }
        var out = ""
        var letters = 0
        let chars = Array(text)
        var i = 0
        while i < chars.count {
            let c = chars[i]
            if c == "%" {
                // Copy a format specifier verbatim: %@ %d %ld %lld %1$@ %.1f %%
                var j = i + 1
                while j < chars.count, "0123456789$.-+ #'lhqLzjt".contains(chars[j]) { j += 1 }
                if j < chars.count { j += 1 }
                out += String(chars[i..<min(j, chars.count)])
                i = j
                continue
            }
            if let accented = accents[c] {
                out.append(accented)
                letters += 1
            } else {
                out.append(c)
                if c.isLetter { letters += 1 }
            }
            i += 1
        }
        let padding = Int((Double(max(letters, 1)) * expansion).rounded(.up))
        return "[" + out + String(repeating: "·", count: padding) + "]"
    }
}
